   assert.match(a.report, /mustache\.js/);
   assert.match(a.jsonata, /"bio": bio = "" \? null : bio/);
   // structured findings drive the Truthiness dock panel.
   assert.equal(a.findings.length, 1);
   const f = a.findings[0];
